Let Assumptions A:A1 and A:z hold, $\mathcal{L}_1$ and $\Psi$ be as defined in (8), and $\Gamma$ in (9). Let $\nu$ the conditional measure of $\mu$ on $\mathcal{L}_1$, obtained by its disintegration w.r.t. the foliation $\mathcal{F}$ from 7. Then 
\begin{enumerate}[(i)]
	\item $\Psi$ is a measure preserving, continuous conjugacy between the suspension flow $\Gamma^t$ and the flow $\Phi^{2\pi t/\omega}$ :

     \[ \Psi\circ \Gamma^t = \Phi^{2\pi t/\omega} \circ \Psi , \quad \forall t\in \mathbb{R} . \]

	\item Let $\zeta$ be an $L^2(\mu)$ (or $C(X)$ ) eigenfunction of $V$ with frequency $\omega'$, i.e., $V\zeta = \iota \omega' \zeta$. Then the map 

        \begin{equation} 
	   \tilde{\zeta} : \mathcal{L}_1 \to \mathbb{C}, \quad x \mapsto \zeta \left( \Psi(x,0) \right); \quad \forall x\in \mathcal{L}_1,
	\end{equation}

	is an $L^2(\mu | \mathcal{L}_1)$ (or $C(\mathcal{L}_1)$ ) eigenfunction of the return map $R$ with eigenvalue  $e^{\iota 2\pi \omega'/\omega}$.
	\item Conversely, for any $L^2(\nu)$ (or $C(X)$ ) eigenfunction $\tilde{\zeta}$ of $R$ with eigenvalue $e^{\iota 2\pi \omega'/\omega}$, the map 

    \begin{equation}
	\zeta :X\to\mathbb{C}, \quad	\zeta\left(  \Psi(y,s)  \right) := e^{ \iota 2 \pi \omega' s/\omega} \zeta(y); \quad \forall y\in \mathcal{L}_1, s\in [0,1)
    \end{equation}

    is an $L^2(\mu)$ (or $C(M)$ ) eigenfunction for $V$ with eigenfrequency $\omega'$.
\end{enumerate}

Let Assumption A:A1 hold, and let $z:M\to S^1 \subset \mathbb{C}$ be a $C^1$ eigenfunction with eigenfrequency $\omega$. Let $\mathcal{F}$ be the resulting foliation as in (7), and $\mathcal{L}_1$ be the leaf as in Assumption A:z. Let $\nabla_\tau$ be the gradient of $z$ with respect to a metric $\tau$ on $M$, as described in (12). Let $\tau$ be conformally transformed, so that $\nabla z$ is a unit vector field.  Define the vector field

\begin{equation}
\tilde{V} := V - \omega \nabla_{\tau} z
\end{equation}

Then the following hold. 
\begin{enumerate}[(i)]
    \item The vector field $\tilde{V}$ is tangent to the foliation $\mathcal{F}$. In particular, $\tilde{V}(z) = 0$ .
    \item $\tilde{V}$ is invariant under the flow $\Phi^t$, i.e., for every $x\in M$, every $t\in\mathbb{R}$, $\Phi^{t}_*|_x \tilde{V}(x)$ = $\tilde{V}\left( \Phi^{t} x \right)$. 
    \item The flow $\tilde{\Phi}^t$ := $\Phi^t_{\tilde{V}}$ generated by $\tilde{V}$ commutes with $\Phi^t$.
\end{enumerate}
